  "source": "def render(rows, block=False):
    escapes = {"\\": "\\\\", "|": "\\|", "\n": "\\n"}

    def encode(field):
        if block and "\n" in field:
            return '"' + field.replace('"', '""') + '"'
        return "".join(escapes.get(char, char) for char in field)

    return "".join("|".join(encode(field) for field in row) + "\n" for row in rows)
